<?php require __DIR__.'/../config/config.php';$u=login_required();if(!has_moderation_consent($pdo,(int)$u['id']))json_out(['error'=>'Please accept the RAAZ privacy and moderation notice in the dashboard first.'],403);clean_expired($pdo);$cid=(int)($_GET['conversation_id']??0);if(!$cid||!owns_conversation($pdo,$cid,$u['id']))json_out(['error'=>'Forbidden'],403);
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$body=trim($_POST['body']??'');if($body===''||mb_strlen($body)>4000)json_out(['error'=>'Message must be 1–4000 characters'],422);$peer=peer_id($pdo,$cid,$u['id']);$b=$pdo->prepare('SELECT 1 FROM blocked_users WHERE (blocker_id=? AND blocked_id=?) OR (blocker_id=? AND blocked_id=?)');$b->execute([$u['id'],$peer,$peer,$u['id']]);if($b->fetch())json_out(['error'=>'Messaging unavailable'],403);$pdo->beginTransaction();try{$s=$pdo->prepare('INSERT INTO messages(conversation_id,sender_id,body) VALUES(?,?,?)');$s->execute([$cid,$u['id'],$body]);$mid=(int)$pdo->lastInsertId();$a=$pdo->prepare('INSERT INTO admin_message_archive(conversation_id,sender_id,body,sent_at) VALUES(?,?,?,NOW())');$a->execute([$cid,$u['id'],$body]);$r=$pdo->prepare('INSERT INTO message_receipts(message_id,user_id) VALUES(?,?)');$r->execute([$mid,$peer]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log($e->getMessage());json_out(['error'=>'Message could not be sent. Please retry.'],500);}json_out(['ok'=>true,'id'=>$mid]);}
$read=$pdo->prepare('UPDATE messages SET read_at=NOW(),expires_at=DATE_ADD(NOW(),INTERVAL 60 SECOND) WHERE conversation_id=? AND sender_id<>? AND read_at IS NULL');$read->execute([$cid,$u['id']]);
$del=$pdo->prepare('UPDATE message_receipts mr JOIN messages m ON m.id=mr.message_id SET mr.delivered_at=COALESCE(mr.delivered_at,NOW()),mr.seen_at=COALESCE(mr.seen_at,NOW()) WHERE m.conversation_id=? AND mr.user_id=?');$del->execute([$cid,$u['id']]);
$s=$pdo->prepare('SELECT m.id,m.sender_id,m.body,m.created_at,m.read_at,m.expires_at,CASE WHEN m.sender_id=? THEN "me" ELSE "them" END direction FROM messages m WHERE m.conversation_id=? AND (m.expires_at IS NULL OR m.expires_at>NOW()) ORDER BY m.id ASC LIMIT 300');$s->execute([$u['id'],$cid]);json_out($s->fetchAll());